          apiKey,
          clientType,
          body,
          upstreamResponse,
          lease,
          startedAt,
          lease.config().id(),
          clientIp,
          userAgent,
          request.getHeader("x-client-request-id"),
          requestMethod,
          requestUri,
          queryString);
