  private String extractProxyApiKey(String authorization, String xApiKey) {
    String bearer = extractBearerOrNull(authorization);
    if (bearer != null) {
      return bearer;
    }
    if (xApiKey != null && !xApiKey.isBlank()) {
      return xApiKey.trim();
